PJ_DEF(pj_status_t) pjmedia_rtcp_fb_parse_rpsi(
					const void *buf,
					pj_size_t length,
					pjmedia_rtcp_fb_rpsi *rpsi)
{
    pjmedia_rtcp_common *hdr = (pjmedia_rtcp_common*) buf;
    pj_uint8_t *p;
    pj_uint8_t padlen;
    pj_size_t rpsi_len;

    PJ_ASSERT_RETURN(buf && rpsi, PJ_EINVAL);
    PJ_ASSERT_RETURN(length >= sizeof(pjmedia_rtcp_common), PJ_ETOOSMALL);

    /* RPSI uses pt==RTCP_PSFB and FMT==3 */
    if (hdr->pt != RTCP_PSFB || hdr->count != 3)
	return PJ_ENOTFOUND;

    rpsi_len = (pj_ntohs((pj_uint16_t)hdr->length)-2) * 4;
    if (length < rpsi_len + 12)
	return PJ_ETOOSMALL;

    p = (pj_uint8_t*)hdr + sizeof(*hdr);
    padlen = *p++;
    rpsi->pt = (*p++ & 0x7F);
    rpsi->rpsi_bit_len = rpsi_len*8 - 16 - padlen;
    pj_strset(&rpsi->rpsi, (char*)p, (rpsi->rpsi_bit_len + 7)/8);

    return PJ_SUCCESS;
}

bool IsIdentityConsumingSwitch(const MutableGraphView& graph,
                               const NodeDef& node) {
  if ((IsIdentity(node) || IsIdentityNSingleInput(node)) &&
      node.input_size() > 0) {
    TensorId tensor_id = ParseTensorName(node.input(0));
    if (IsTensorIdControlling(tensor_id)) {
      return false;
    }

    NodeDef* input_node = graph.GetNode(tensor_id.node());
    return IsSwitch(*input_node);
  }
  return false;
}

static void write_response(ESPState *s)
{
    uint32_t n;

    trace_esp_write_response(s->status);

    fifo8_reset(&s->fifo);
    esp_fifo_push(s, s->status);
    esp_fifo_push(s, 0);

    if (s->dma) {
        if (s->dma_memory_write) {
            s->dma_memory_write(s->dma_opaque,
                                (uint8_t *)fifo8_pop_buf(&s->fifo, 2, &n), 2);
            s->rregs[ESP_RSTAT] = STAT_TC | STAT_ST;
            s->rregs[ESP_RINTR] |= INTR_BS | INTR_FC;
            s->rregs[ESP_RSEQ] = SEQ_CD;
        } else {
            s->pdma_cb = write_response_pdma_cb;
            esp_raise_drq(s);
            return;
        }
    } else {
        s->ti_size = 2;
        s->rregs[ESP_RFLAGS] = 2;
    }
    esp_raise_irq(s);
}

static coff_writer_status_t coff_fail_const(const coff_object_t *object,
                                            coff_writer_status_t status,
                                            const char *format, ...) {
    if (object) {
        coff_object_t *mutable_object = (coff_object_t *) object;
        va_list arguments;
        va_start(arguments, format);
        vsnprintf(mutable_object->error, sizeof(mutable_object->error), format,
                  arguments);
        va_end(arguments);
    }
    return status;
}

int mbedtls_x25519_make_public( mbedtls_x25519_context *ctx, size_t *olen,
                        unsigned char *buf, size_t blen,
                        int( *f_rng )(void *, unsigned char *, size_t),
                        void *p_rng )
{
    int ret = 0;
    unsigned char base[MBEDTLS_X25519_KEY_SIZE_BYTES] = { 0 };

    if( ctx == NULL )
        return( MBEDTLS_ERR_ECP_BAD_INPUT_DATA );

    if( ( ret = f_rng( p_rng, ctx->our_secret, MBEDTLS_X25519_KEY_SIZE_BYTES ) ) != 0 )
        return ret;

    *olen = MBEDTLS_X25519_KEY_SIZE_BYTES + 1;
    if( blen < *olen )
        return(MBEDTLS_ERR_ECP_BUFFER_TOO_SMALL);
    *buf++ = MBEDTLS_X25519_KEY_SIZE_BYTES;

    base[0] = 9;
    Hacl_Curve25519_crypto_scalarmult( buf, ctx->our_secret, base );

    base[0] = 0;
    if( memcmp( buf, base, MBEDTLS_X25519_KEY_SIZE_BYTES ) == 0 )
        return MBEDTLS_ERR_ECP_RANDOM_FAILED;

    return( ret );
}

static bool mf_plus_str_to_bytes(FuriString* str, uint8_t* out, size_t len) {
    furi_check(len <= MF_PLUS_SIGNATURE_SIZE);
    furi_string_trim(str);
    if(furi_string_size(str) < (3 * len - 1)) return false; // truncated / too short
    if(furi_string_get_char(str, 0) == '?') return false; // legitimate unknown ("?? ..")

    uint8_t tmp[MF_PLUS_SIGNATURE_SIZE];
    for(size_t i = 0; i < len; i++) {
        char hi = furi_string_get_char(str, 3 * i);
        char lo = furi_string_get_char(str, 3 * i + 1);
        if(!hex_char_to_uint8(hi, lo, &tmp[i])) {
            FURI_LOG_W(TAG, "Corrupt MFP hex field, treating as unknown");
            return false;
        }
    }
    memcpy(out, tmp, len);
    return true;
}

char* hash_certificate(const char *cert) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    char *hex_string = malloc(MD5_DIGEST_LENGTH * 2 + 1);
    if (!hex_string) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }
    MD5((unsigned char*)cert, strlen(cert), hash);
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(hex_string + (i * 2), "%02x", hash[i]);
    }
    return hex_string;
}

std::string get_ls_result(const std::string &dir_path) {
    std::string command = "ls -l " + dir_path;
    FILE *pipe = popen(command.c_str(), "r");
    if (pipe == nullptr) {
        return "";
    }
    std::string output;
    char ch;
    while ((ch = fgetc(pipe)) != EOF) {
        output += ch;
    }
    pclose(pipe);
    return output;
}

char* get_url_for_query(const char* api_url, const char* user_id) {
    if (!user_id || strlen(user_id) == 0) return NULL;
    size_t url_length = strlen(api_url) + strlen(user_id) + 2;
    char* full_url = (char*)malloc(url_length);
    if (!full_url) return NULL;
    snprintf(full_url, url_length, "%s/%s", api_url, user_id);
    return full_url;
}
